from pathlib import Path
import json,math,hashlib
R=Path(__file__).resolve().parent.parent
cur=json.loads((R/'data/retrieval-candidates.json').read_text(encoding='utf-8'))
items=cur.get('items',cur.get('candidates',[]));by={v.get('candidateId',v.get('id')):v for v in items}
raw=json.loads((R/'data/shot-candidates.json').read_text(encoding='utf-8'));tags={v['id']:v for v in raw['items']}
# Rhythm follows measured onset candidates but preserves a deliberate breathing chapter.
bounds=[0,13,31,45,57,80,102,124,146,168,176,210,244,278,312,336,360,386,411,436,460,486,510,536,561,588,612,638,662,688,714,740,765,790,816,842,866,892,918,944,970,996,1022,1048,1074,1100,1126,1152,1178,1204,1230,1256,1282,1308,1334,1360,1386,1416,1440]
ids=[3,20,33,84,37,38,56,79,14,None,11,46,31,71,10,12,13,24,17,21,26,27,16,32,34,37,39,42,48,49,86,87,92,93,94,97,56,57,58,61,63,64,50,51,52,53,65,67,71,72,75,20,27,79,82,86,97,75]
assert len(ids)==len(bounds)-1,(len(ids),len(bounds))
shots=[]
for i,(n,a,b) in enumerate(zip(ids,bounds,bounds[1:])):
    if n is None:shots.append({'id':f'S{i+1:03}','kind':'black','startFrame':a,'frames':b-a,'reason':'V20明确黑场停顿的改编，不是丢帧'});continue
    cid=f'S1C{n:03}';t=tags[cid];c=by[cid]
    window=c.get('recommendedCoreSearchSeconds',t['suggestedSearchWindowSeconds'])
    # Core intervals are conservative search intervals, not exact certified cut edges.
    if isinstance(window,dict):window=[window.get('start',window.get('in')),window.get('end',window.get('out'))]
    duration=(b-a)/24;available=window[1]-window[0]
    rate=min(1.0,available/max(duration,.001)*.92)
    rate=max(.15,round(rate,6));source_span=duration*rate
    assert source_span<=available+.001,(cid,source_span,available)
    start=window[0]+max(0,(available-source_span)/2)
    shots.append({'id':f'S{i+1:03}','kind':'video','candidateId':cid,'sourceId':t['sourceId'],'sourcePath':t['sourcePath'],'episode':t['episode'],'startFrame':a,'frames':b-a,'sourceInSeconds':round(start,6),'sourceOutSeconds':round(start+source_span,6),'playbackRate':rate,'searchWindowSeconds':window,'exactNativeCutBoundaryStatus':'pending_execution_decode_check','focus':t['visibleActionOrPose'],'characters':t['characters'],'palette':t['dominantPalette'],'preflightEvidence':c.get('contactSheet',t.get('contactSheet')),'motionEvidence':c.get('observedMovement','see_motion_preflight_and_curator'),'reframe':{'scale':1,'x':0,'y':0},'sourceVFX':'source animation, not newly authored CG'})
